use lcs::lcs;

#[test]
fn test_both_empty() {
    assert_eq!(lcs("", ""), 0);
}

#[test]
fn test_identical() {
    assert_eq!(lcs("abc", "abc"), 3);
}

#[test]
fn test_subsequence() {
    assert_eq!(lcs("abcde", "ace"), 3);
}

#[test]
fn test_no_common() {
    assert_eq!(lcs("abc", "def"), 0);
}
